154:             if (generated == null) throw new IllegalArgumentException("模型未返回画像提案");
155:             if (generated.proposedProfile().equals(current.content()) || generated.changes().isEmpty()) {
156:                 writeState(userId, new MaintenanceState(bundle.fingerprint(), Instant.now(), "no_changes"));
157:                 return;
