178:         List<ProfileGenerationRequest.MemoryEvidence> evidence = new ArrayList<>();
179:         StringBuilder fingerprintMaterial = new StringBuilder();
180:         int remaining = EVIDENCE_TOKEN_BUDGET;
181:         for (Path path : memoryFiles(workspace)) {
182:             String content = readSmallFile(path);
183:             if (content == null) continue;
184:             if (path.getFileName().toString().equals("MEMORY.md")) {
185:                 content = USER_PROFILE_SECTION.matcher(content).replaceFirst("");
186:             }
187:             String relative = workspace.relativize(path).toString().replace('\\', '/');
188:             fingerprintMaterial.append(relative).append('\n').append(content).append('\n');
189:             for (String paragraph : content.split("\\R\\s*\\R")) {
190:                 String normalized = paragraph.strip();
