171:         if (!Files.exists(file)) return new TurnSnapshot(null, null);
172:         int maximum = 8 * 1024 * 1024;
173:         try (var input = Files.newInputStream(file)) {
174:             byte[] bytes = input.readNBytes(maximum + 1);
175:             if (bytes.length > maximum) throw new IllegalArgumentException("来源会话超过单次核对预算");
176:             TranscriptMessageDto user = null, assistant = null;
177:             for (String line : new String(bytes, StandardCharsets.UTF_8).split("\\R")) {
178:                 if (line.isBlank()) continue;
179:                 TranscriptMessageDto message = objectMapper.readValue(line, TranscriptMessageDto.class);
180:                 if (!java.util.Objects.equals(turnId, message.turnId())) continue;
181:                 if (message.role() == null) throw new IllegalArgumentException("来源轮次角色不明确");
182:                 if (message.role() == TranscriptMessageDto.MessageRole.USER) {
183:                     if (user != null) throw new IllegalArgumentException("来源轮次存在重复用户记录");
184:                     user = message;
185:                 } else {
186:                     if (assistant != null) throw new IllegalArgumentException("来源轮次存在重复终态");
187:                     assistant = message;
188:                 }
189:             }
190:             return new TurnSnapshot(user, assistant);
191:         } catch (IOException exception) { throw new IllegalArgumentException("来源会话暂不可核对"); }
192:     }
