93:                         c.draft().observations().stream().limit(2).forEach(o -> lines.add("- 回顾：" + o.text()));
94:                         if (c.draft().followUps() != null) {
95:                             c.draft().followUps().stream().limit(1).forEach(f -> lines.add("- 跟进：" + f.text()));
96:                         }
97:                         c.draft().actions().stream().limit(2).forEach(a -> lines.add("- 小步建议：" + a.text()));
98:                         String summary = String.join("\n", lines);
99:                         if (summary.length() > 360) summary = summary.substring(0, 360);
