226: function buildActivity(daily: DailyTokenUsage[]) {
227:   const values = new Map(daily.map((item) => [item.date, item.totalTokens]));
228:   const activeDates = new Set(daily.filter((item) => item.totalTokens > 0).map((item) => item.date));
229:   const peakTokens = Math.max(0, ...daily.map((item) => item.totalTokens));
230:   const today = startOfLocalDay(new Date());
231:   const rangeStart = addDays(today, -364);
232:   const heatPeak = Math.max(0, ...daily
233:     .filter((item) => item.date >= formatLocalDate(rangeStart) && item.date <= formatLocalDate(today))
234:     .map((item) => item.totalTokens));
235:   const gridStart = addDays(rangeStart, -(mondayIndex(rangeStart)));
236:   const gridEnd = addDays(today, 6 - mondayIndex(today));
237:   const weeks: ActivityWeek[] = [];
238:   let previousMonth = -1;
239: 
240:   for (let cursor = gridStart; cursor <= gridEnd; cursor = addDays(cursor, 7)) {
241:     const days = Array.from({ length: 7 }, (_, offset) => {
242:       const date = addDays(cursor, offset);
243:       const dateKey = formatLocalDate(date);
244:       const tokens = values.get(dateKey) ?? 0;
245:       return {
246:         date: dateKey,
247:         tokens,
248:         level: heatLevel(tokens, heatPeak),
249:         inRange: date >= rangeStart && date <= today,
250:       };

