20: /** 在真实 Model Call 前临时注入已组装上下文，不修改 AgentState 中的消息。 */
21: @Component
22: @lombok.extern.slf4j.Slf4j
23: public class ContextInjectionMiddleware implements MiddlewareBase {
24: 
25:     private butvan.agent.agents.usage.TokenCounter tokenCounter = new butvan.agent.agents.usage.ApproximateTokenCounter();
26:     /** 失效过滤后沿用项目同一计数器重建信封和归因元数据。 */
27:     @org.springframework.beans.factory.annotation.Autowired(required = false)
28:     public void setTokenCounter(butvan.agent.agents.usage.TokenCounter counter) { this.tokenCounter = counter; }
29: 
30:     public static final String CONTEXT_METADATA_KEY = "butvan_managed_context";
31:     public static final String PROFILE_TOKENS_METADATA_KEY = "butvan_profile_tokens";
32:     public static final String MEMORY_TOKENS_METADATA_KEY = "butvan_memory_tokens";
33: 
34:     @Override
35:     public Flux<AgentEvent> onModelCall(
36:             Agent agent,
37:             RuntimeContext context,
38:             ModelCallInput input,
39:             Function<ModelCallInput, Flux<AgentEvent>> next
40:     ) {
41:         ContextEnvelope envelope = context == null ? null : context.get(ContextEnvelope.class);
42:         if (envelope != null) {
43:             envelope = revalidate(envelope);
44:             // 失效后永久移出本轮信封，重新开启开关也不能复活同一份旧缓存。
45:             context.put(ContextEnvelope.class, envelope);
46:         }
47:         if (envelope == null || envelope.isEmpty() || input == null || input.messages() == null) {
48:             return next.apply(input);
49:         }
50: 
51:         int currentUserIndex = findCurrentUser(input.messages(), context.get(TokenUsageRoundContext.class));
52:         if (currentUserIndex < 0) return next.apply(input);
53: 
54:         List<Msg> messages = new ArrayList<>(input.messages());
55:         messages.add(currentUserIndex, UserMessage.builder()
56:                 .name("managed_context")
57:                 .textContent(envelope.rendered())
58:                 .metadata(Map.of(
59:                         Msg.METADATA_SYNTHETIC, true,
60:                         Msg.METADATA_REMINDER_KIND, CONTEXT_METADATA_KEY,
61:                         CONTEXT_METADATA_KEY, true,
62:                         PROFILE_TOKENS_METADATA_KEY, envelope.profileTokens(),
63:                         MEMORY_TOKENS_METADATA_KEY, envelope.memoryTokens()))
64:                 .build());
65:         return next.apply(new ModelCallInput(messages, input.tools(), input.options(), input.model()));
66:     }
67: 
68:     private int findCurrentUser(List<Msg> messages, TokenUsageRoundContext round) {
69:         if (round == null) return -1;
70:         for (int index = 0; index < messages.size(); index++) {
71:             Msg message = messages.get(index);
72:             if (message == null || message.getRole() != MsgRole.USER || message.getMetadata() == null) continue;
73:             if (round.turnId().equals(
74:                     message.getMetadata().get(TokenUsageRoundContext.TURN_METADATA_KEY))) return index;
75:         }
76:         return -1;
77:     }
78: 
79:     private ContextEnvelope revalidate(ContextEnvelope envelope) {
80:         try {
81:             if (!envelope.stillCurrent().getAsBoolean()) return ContextEnvelope.empty();
82:             var kept = envelope.blocks().stream().filter(block -> {
83:                 try { return block.stillCurrent().getAsBoolean(); }
84:                 catch (RuntimeException exception) {
85:                     log.warn("上下文片段失效检查失败：errorType={}", exception.getClass().getSimpleName()); return false;
86:                 }
87:             }).toList();
88:             return kept.size() == envelope.blocks().size() ? envelope
89:                     : ContextEnvelopeBuilder.build(kept, envelope.estimatedTokens(), tokenCounter, envelope.stillCurrent());
90:         } catch (RuntimeException exception) {
91:             log.warn("上下文有效性检查失败：errorType={}", exception.getClass().getSimpleName()); return ContextEnvelope.empty();
92:         }
93:     }
94: }

