132:     private String readSmallFile(String userId, Path path) {
133:         try {
134:             if (!isSafeReadableFile(userId, path)
135:                     || Files.size(path) > MAX_FILE_BYTES) return null;
136:             return Files.readString(path, StandardCharsets.UTF_8);
137:         } catch (IOException exception) {
138:             log.warn("读取个人上下文文件失败：path={}", path, exception);
139:             return null;
140:         }
141:     }
142: 
143:     private void writeAtomically(Path target, String content) {
144:         try {
145:             Path userWorkspace = target.getParent().getParent();
146:             if (Files.isSymbolicLink(userWorkspace) || Files.isSymbolicLink(target.getParent())) {
147:                 throw new IllegalStateException("个人上下文目录不能是符号链接");
148:             }
149:             Files.createDirectories(target.getParent());
150:             if (Files.isSymbolicLink(target)) throw new IllegalStateException("个人上下文文件不能是符号链接");
151:             Path temporary = Files.createTempFile(target.getParent(), ".personal-context-", ".tmp");
152:             try {
153:                 Files.writeString(temporary, content, StandardCharsets.UTF_8);
154:                 try {
155:                     Files.move(temporary, target, StandardCopyOption.ATOMIC_MOVE,
156:                             StandardCopyOption.REPLACE_EXISTING);
157:                 } catch (AtomicMoveNotSupportedException exception) {
158:                     Files.move(temporary, target, StandardCopyOption.REPLACE_EXISTING);
159:                 }
160:             } finally {
161:                 Files.deleteIfExists(temporary);
162:             }
163:         } catch (IOException exception) {
164:             throw new IllegalStateException("保存个人上下文失败", exception);
165:         }
166:     }
167: 
168:     private boolean isSafeReadableFile(String userId, Path path) {
169:         Path userWorkspace = storageProperties.userWorkspaceDirectory(userId);
170:         return !Files.isSymbolicLink(userWorkspace)
171:                 && !Files.isSymbolicLink(path.getParent())
172:                 && !Files.isSymbolicLink(path)
173:                 && Files.isRegularFile(path);
174:     }
175: 
176:     private record Settings(boolean enabled, boolean maintenanceEnabled) {
177:         private static Settings defaults() {
178:             return new Settings(true, false);
179:         }
180:     }
181: }

