249:     private PriorContext priorContext(Content current, Settings s) {
250:         LocalDate earliest = current.day().minusDays(Math.max(1, s.historyDays()));
251:         Set<LocalDate> seenDays = new HashSet<>();
252:         List<ReviewGenerationRequest.HistoryAction> actions = new ArrayList<>();
253:         List<ReviewGenerationRequest.Observation> observations = new ArrayList<>();
254:         for (var item : repository.history(current.owner())) {
255:             if (item.id().equals(current.id()) || !"READY".equals(item.state()) || item.draft() == null) continue;
256:             if (!item.grantId().equals(s.grantId()) || item.settingsRevision() != s.revision()) continue;
257:             if (item.day().isAfter(current.day()) || item.day().isBefore(earliest) || !seenDays.add(item.day())) continue;
258:             if (item.draft().actions() != null) {
259:                 for (int i = 0; i < item.draft().actions().size() && actions.size() < 3; i++) {
260:                     var a = item.draft().actions().get(i);
261:                     int checkDays = a.checkAfterDays() == null ? 7 : a.checkAfterDays();
262:                     actions.add(new ReviewGenerationRequest.HistoryAction(
263:                             "act-" + item.day() + "-" + (i + 1),
264:                             a.topicKey(),
265:                             a.text(),
266:                             "SUGGESTED",
267:                             item.day().plusDays(checkDays).toString(),
268:                             "往期建议，未反馈不视为失败"));
269:                 }
270:             }
271:             if (item.draft().observations() != null) {
272:                 for (int i = 0; i < item.draft().observations().size() && observations.size() < 3; i++) {
273:                     var o = item.draft().observations().get(i);
274:                     observations.add(new ReviewGenerationRequest.Observation(
275:                             "obs-" + item.day() + "-" + (i + 1),
276:                             o.topicKey(),
277:                             o.text(),
278:                             o.uncertainty()));
279:                 }
280:             }
281:             if (actions.size() >= 3 && observations.size() >= 3) break;
282:         }
283:         return new PriorContext(List.copyOf(actions), List.copyOf(observations));
284:     }
