8: /** 设置快照与写入操作编排；组件卸载后不发布迟到加载结果。 */
9: export function useLifeReview() {
10:   const [settings, setSettings] = useState<LifeSettings | null>(null);
11:   const [history, setHistory] = useState<LifeContent[]>([]);
12:   const [candidates, setCandidates] = useState<LifeCandidate[]>([]);
13:   const [habit, setHabit] = useState<LifeHabit | null>(null);
14:   const [habitSuggestion, setHabitSuggestion] = useState<LifeHabitSuggestion | null>(null);
15:   const [nudges, setNudges] = useState<LifeNudge[]>([]);
16:   const [archives, setArchives] = useState<string[]>([]);
17:   const [providers, setProviders] = useState<FullModelConfig['providers']>([]);
18:   const [busy, setBusy] = useState(false);
19:   const [loading, setLoading] = useState(true);
20:   const [error, setError] = useState('');
21:   const [dirty, setDirty] = useState(false);
22:   const live = useRef(false);
23:   const sequence = useRef(0);
24:   const saved = useRef<LifeSettings | null>(null);
25:   const { showMessage } = useMessage();
26:   const load = useCallback(async () => {
27:     const seq = ++sequence.current;
28:     try {
29:       const [s, h, c, habitValue, suggestionValue, nudgesValue, a, models] = await Promise.all([
30:         lifeReviewApi.settings(), lifeReviewApi.history(), lifeReviewApi.candidates(), lifeReviewApi.habit(),
31:         lifeReviewApi.habitSuggestion().catch(() => null), lifeReviewApi.nudges().catch(() => []),
32:         lifeReviewApi.archives(), fetchFullModelConfig(),
33:       ]);
34:       if (!live.current || seq !== sequence.current) return;
35:       const normalized = { ...s, idleCheckinDays: s.idleCheckinDays ?? 0 };
36:       saved.current = normalized;
37:       setSettings(normalized); setHistory(h); setCandidates(c); setHabit(habitValue);
38:       setHabitSuggestion(suggestionValue && typeof suggestionValue.available === 'boolean' ? suggestionValue : null);
39:       setNudges(Array.isArray(nudgesValue) ? nudgesValue : []);
40:       setArchives(a);
41:       setProviders(models?.providers || []); setError(''); setDirty(false);
42:     } catch (e) {
43:       if (live.current && seq === sequence.current) setError(e instanceof Error ? e.message : '生活复盘读取失败');
44:     } finally { if (live.current && seq === sequence.current) setLoading(false); }
45:   }, []);
46:   useEffect(() => { live.current = true; void load(); return () => { live.current = false; }; }, [load]);
47:   const generating = history.some(item => item.state === 'PENDING' || item.state === 'RUNNING');
48:   useEffect(() => {
49:     if (!generating) return;
50:     const timer = window.setInterval(() => { if (live.current) void load(); }, 2000);
51:     return () => window.clearInterval(timer);
52:   }, [generating, load]);
53:   async function act(work: () => Promise<unknown>, message: string) {
54:     if (busy) return;
55:     setBusy(true);
56:     try { await work(); if (live.current) { showMessage('success', message); await load(); } }
57:     catch (e) { if (live.current) showMessage('error', e instanceof Error ? e.message : '操作未完成'); }
58:     finally { if (live.current) setBusy(false); }
59:   }
60:   function patch(next: Partial<LifeSettings>) { setSettings(s => s ? { ...s, ...next } : s); setDirty(true); }
61:   function discard() { setSettings(saved.current); setDirty(false); }
62:   return { discard, settings, history, candidates, habit, habitSuggestion, nudges, archives, providers, busy, loading, generating, error, dirty, patch, load, act };
63: }

