146:             let _ = std::process::Command::new("/usr/bin/osascript")
147:                 .args([
148:                     "-e",
149:                     "on run argv\ndisplay notification (item 2 of argv) with title (item 1 of argv)\nend run",
150:                     "--",
151:                     &title,
152:                     &body,
153:                 ])
154:                 .spawn();
155:             if sound {
156:                 app.run_on_main_thread(|| {
157:                     use objc2_app_kit::NSSound;
158:                     use objc2_foundation::NSString;
159:                     let played = NSSound::soundNamed(&NSString::from_str("Ping"))
160:                         .is_some_and(|tone| tone.play());
