167:                     }
168:                 }).map_err(|e| format!("提醒声音无法播放：{}", e))?;
169:             }
170:             return Ok(());
171:         }
172:         let mut settings = task_notification_status();
173:         if !settings.authorized {
174:             let _ = crate::notification_authorization::request();
175:             settings = task_notification_status();
176:         }
177:         if !settings.authorized || !settings.alert_enabled {
178:             return Err("请在系统设置 → 通知 → ButvanAgent 开启通知横幅".into());
179:         }
180:         let mut notification = mac_usernotifications::Notification::new().title(title).message(body);
181:         if sound { notification = notification.default_sound(); }
182:         return notification.send_blocking()
183:             .map(|_| ())
184:             .map_err(|e| { log::warn!("任务原生通知提交失败：{}", e); "系统通知提交失败，请检查系统通知设置".into() });
185:     }
186:     #[cfg(not(target_os = "macos"))]
187:     {
188:         use tauri_plugin_notification::NotificationExt;
189:         let mut notification = app.notification().builder().title(title).body(body);
190:         if sound { notification = notification.sound("default"); }
191:         notification.show().map_err(|e| { log::warn!("任务系统通知提交失败：{}", e); "系统通知提交失败".into() })
192:     }
