1: //! macOS 通知授权：保留系统错误，避免将应用签名错误误报为用户拒绝。
2: 
3: use block2::RcBlock;
4: use objc2::runtime::Bool;
5: use objc2_foundation::NSError;
6: use objc2_user_notifications::{UNAuthorizationOptions, UNUserNotificationCenter};
7: use std::{sync::mpsc, time::Duration};
8: 
9: /// 在后台线程等待系统授权回调；主线程必须继续处理原生弹窗。
10: /// mac-usernotifications 0.3.1 的授权封装忽略 NSError，因此这里直接调用系统 API。
11: pub fn request() -> Result<bool, String> {
12:     mac_usernotifications::check_bundle()
13:         .map_err(|_| "无法识别应用身份，请从“应用程序”中打开完整安装的 App。".to_string())?;
14:     let (sender, receiver) = mpsc::sync_channel(1);
15:     UNUserNotificationCenter::currentNotificationCenter()
16:         .requestAuthorizationWithOptions_completionHandler(
17:             UNAuthorizationOptions::Alert | UNAuthorizationOptions::Sound,
18:             &RcBlock::new(move |granted: Bool, error: *mut NSError| {
19:                 // NSError 仅在回调期间借用，将所需信息复制为 Rust 字符串。
20:                 let result = match unsafe { error.as_ref() } {
21:                     Some(error) => {
22:                         log::warn!(
23:                             "通知授权请求失败：{} ({})：{}",
24:                             error.domain(),
25:                             error.code(),
26:                             error.localizedDescription()
27:                         );
28:                         Err(format!(
29:                             "系统通知授权请求失败（{} / {}），请检查应用安装与签名后重试。",
30:                             error.domain(),
31:                             error.code()
32:                         ))
33:                     }
34:                     None => Ok(granted.as_bool()),
35:                 };
36:                 if sender.send(result).is_err() {
37:                     log::warn!("通知授权回调到达时请求已结束");
38:                 }
39:             }),
40:         );
41:     receiver
42:         .recv_timeout(Duration::from_secs(120))
43:         .map_err(|_| "等待系统通知授权超时，请完成系统弹窗后重试。".to_string())?
44: }

