277:         CompanionState state = store.load(owner);
278:         Settings s = repository.settings(owner);
279:         if (!s.enabled() || !s.proactive() || !state.rhythm().companionEnabled()) return;
280: 
281:         Instant now = automationClock.instant();
282:         ZoneId zone = ZoneId.of(s.timezone());
283:         ZonedDateTime local = now.atZone(zone);
284: 
285:         Instant latestUser = resolveLatestUserActivity(owner, zone, now).orElse(state.rhythm().lastUserActiveAt());
286:         RhythmState rhythm = state.rhythm();
287:         if (latestUser != null && rhythm.lastOutreachAt() != null && latestUser.isAfter(rhythm.lastOutreachAt())
288:                 && (rhythm.unansweredCount() > 0 || rhythm.busyDeferred())) {
289:             rhythm = new RhythmState(
290:                     rhythm.companionEnabled(), 0, false, rhythm.lastOutreachHook(),
291:                     rhythm.lastLearnedAt(), rhythm.lastDataFingerprint(), rhythm.lastOutreachAt(),
292:                     latestUser, computeNextReachAt(now, zone, state.cognition(), 0, false));
293:             state = store.save(owner, new CompanionState(state.cognition(), rhythm, state.desktopNotices()));
294:         }
295: 
296:         learnIfDue(owner);
297:         state = store.load(owner);
298:         rhythm = state.rhythm();
299:         Cognition cog = state.cognition();
300: 
301:         if (local.getHour() < 8 || local.getHour() >= 23) return;
302:         Instant dueAt = rhythm.nextReachAt();
303:         if (dueAt == null) {
304:             Instant initial = computeNextReachAt(now, zone, cog, rhythm.unansweredCount(), false);
305:             store.save(owner, new CompanionState(cog, new RhythmState(
306:                     rhythm.companionEnabled(), rhythm.unansweredCount(), rhythm.busyDeferred(),
307:                     rhythm.lastOutreachHook(), rhythm.lastLearnedAt(), rhythm.lastDataFingerprint(),
308:                     rhythm.lastOutreachAt(), rhythm.lastUserActiveAt(), initial), state.desktopNotices()));
309:             return;
310:         }
311:         if (now.isBefore(dueAt)) return;
312: 
313:         // 若上次未回复且当前处于用户忙碌时段，不催促，顺延至忙碌时段结束后再自然跟进
314:         if (rhythm.unansweredCount() > 0 && isWithinBusyHours(local.getHour(), cog.busyStartHour(), cog.busyEndHour())) {
315:             Instant deferredTo = deferAfterBusyHours(local, cog.busyEndHour());
316:             RhythmState deferredRhythm = new RhythmState(
317:                     rhythm.companionEnabled(), rhythm.unansweredCount(), true,
318:                     rhythm.lastOutreachHook(), rhythm.lastLearnedAt(), rhythm.lastDataFingerprint(),
319:                     rhythm.lastOutreachAt(), rhythm.lastUserActiveAt(), deferredTo);
320:             store.save(owner, new CompanionState(cog, deferredRhythm, state.desktopNotices()));
321:             return;
322:         }
323: 
324:         String hook = selectHook(cog, rhythm, local);
325:         String text = composeConversationalMessage(cog, rhythm, hook, local);
326:         String dedupKey = "companion:" + local.toLocalDate() + ":" + local.getHour() + ":" + ReviewPolicy.fingerprint(hook);
327:         deliverProactiveMessage(owner, s, "COMPANION_OUTREACH", dedupKey, hook, text, now);
328: 
329:         CompanionState after = store.load(owner);
330:         int nextUnanswered = rhythm.unansweredCount() + 1;
331:         Instant nextReach = computeNextReachAt(now, zone, cog, nextUnanswered, false);
332:         RhythmState nextRhythm = new RhythmState(
333:                 rhythm.companionEnabled(), nextUnanswered, false, hook,
334:                 after.rhythm().lastLearnedAt(), after.rhythm().lastDataFingerprint(),
335:                 now, latestUser, nextReach);
336:         store.save(owner, new CompanionState(after.cognition(), nextRhythm, after.desktopNotices()));
