619:     private static Instant computeNextReachAt(
620:             Instant now, ZoneId zone, Cognition cog, int unansweredCount, boolean immediateAfterBusy
621:     ) {
622:         Duration wait = unansweredCount <= 0
623:                 ? BASE_REACH_INTERVAL
624:                 : BACKOFF_REACH_INTERVAL.multipliedBy(Math.min(3, unansweredCount));
625:         ZonedDateTime candidate = now.plus(wait).atZone(zone);
626:         if (candidate.getHour() >= 23) {
627:             candidate = candidate.toLocalDate().plusDays(1).atTime(Math.max(9, cog.busyEndHour()), 10).atZone(zone);
628:         } else if (candidate.getHour() < 9) {
629:             candidate = candidate.toLocalDate().atTime(9, 30).atZone(zone);
630:         }
631:         if (unansweredCount > 0 && isWithinBusyHours(candidate.getHour(), cog.busyStartHour(), cog.busyEndHour())) {
632:             return deferAfterBusyHours(candidate, cog.busyEndHour());
633:         }
634:         return candidate.toInstant();
635:     }
