51:             } catch (RuntimeException exception) {
52:                 log.warn("复盘事实来源读取失败：domain={} type={}", domain, exception.getClass().getSimpleName());
53:                 sources.add(new SourceStatus(domain, "UNAVAILABLE"));
54:             }
55:         }
56:         facts.sort(Comparator.comparing(Fact::domain).thenComparing(Fact::metricKey)
57:                 .thenComparing(Fact::subjectId).thenComparing(Fact::currency));
