61:     private boolean finance(String owner, LocalDate from, LocalDate to, ZoneId zone, List<Fact> facts) {
62:         Map<String, BigDecimal> incomes = new TreeMap<>(), costs = new TreeMap<>();
63:         for (var item : finance.getReportTransactions(owner, from, to))
64:             if (Set.of("income", "yield").contains(item.transactionType()))
65:                 incomes.merge(item.currency(), item.amount(), BigDecimal::add);
66:         for (var item : expenses.reportExpenses(owner, from, to)) costs.merge(item.currency(), item.amount(), BigDecimal::add);
67:         Set<String> currencies = new TreeSet<>(incomes.keySet());
68:         currencies.addAll(costs.keySet());
69:         for (String currency : currencies) {
70:             BigDecimal income = incomes.getOrDefault(currency, BigDecimal.ZERO), cost = costs.getOrDefault(currency, BigDecimal.ZERO);
71:             facts.add(money("income", "", currency, income));
72:             facts.add(money("expense", "", currency, cost));
73:             facts.add(money("net_cashflow", "", currency, income.subtract(cost)));
74:         }
75:         var assets = finance.getReportAssets(owner, to, zone);
76:         for (var asset : assets) facts.add(money("asset_balance_book_reconstruction", asset.id(), asset.currency(), asset.balance()));
77:         return currencies.isEmpty() && assets.isEmpty();
