88:                     case "monthly" -> date.withDayOfMonth(1).toString();
89:                     default -> "once";
90:                 };
91:                 if (!occurrences.add(todo.id() + ":" + cycle)) continue;
92:                 total++;
93:                 if (todo.completed()) completed++;
94:             }
95:         }
96:         facts.add(new Fact("TODO", "occurrences", "", "", "COUNT", total));
97:         facts.add(new Fact("TODO", "completed", "", "", "COUNT", completed));
98:         return total == 0;
