304:     synchronized void tick() {
305:         if (closed || faulted || (resetBarrier != null && resetBarrier.blocked())) return;
306:         long now = nanoTime.getAsLong();
307:         for (Map.Entry<String, Running> entry : running.entrySet()) {
308:             Task task = store.task(entry.getKey());
309:             Running execution = entry.getValue();
310:             if (execution.control.stopping()) {
311:                 if (task.state() == Execution.RUNNING) {
312:                     store.update(task.id(), t -> t.toBuilder().state(Execution.STOPPING).build());
313:                     delivery.discardNotices(task.id());
314:                     delivery.notice(task, "stopping", "任务正在停止，尚未确认收尾完成。", true,
315:                             () -> store.task(task.id()).state() == Execution.STOPPING);
316:                 }
317:                 continue;
318:             }
319:             if (task.state() == Execution.RUNNING && now - execution.nextHeartbeat >= 0) {
320:                 execution.nextHeartbeat = now + TimeUnit.SECONDS.toNanos(config.heartbeatSeconds());
321:                 long minutes = Math.max(1, TimeUnit.NANOSECONDS.toMinutes(now - execution.started));
322:                 store.update(task.id(), t -> t.toBuilder().nextHeartbeatAt(clock.millis() + config.heartbeatSeconds() * 1000L)
323:                         .stage(execution.control.stage()).build());
324:                 delivery.notice(task, "heartbeat", "任务仍在处理中，已用时约 " + minutes + " 分钟；"
325:                         + execution.control.stage() + "，请稍候。", false,
326:                         () -> store.task(task.id()).state() == Execution.RUNNING && !execution.control.stopping());
327:             }
328:         }
329:         dispatch();
330:         delivery.pump();
331:     }
