362:     private String resolveSession(String conversation) {
363:         String existing = store.snapshot().bindings().get(conversation);
364:         if (existing != null) {
365:             try {
366:                 sessions.requireActive(existing);
367:                 if (sessions.getChannel(existing) == SessionChannel.FEISHU) return existing;
368:                 log.warn("飞书绑定指向其他渠道，将建立独立会话");
369:             }
370:             catch (IllegalArgumentException exception) { log.info("飞书绑定会话已失效，将建立新会话"); }
371:         }
372:         var feishuSessions = sessions.listActive(SessionChannel.FEISHU);
373:         if (feishuSessions != null && !feishuSessions.isEmpty()) {
374:             String latest = feishuSessions.getFirst().id();
375:             store.bind(conversation, latest);
376:             return latest;
377:         }
378:         String created = sessions.createFeishuSession().id();
379:         store.bind(conversation, created);
380:         return created;
381:     }
