396:                 } catch (RuntimeException exception) {
397:                     // 不重试下载：平台图片键有时效，反复重试只会拖延用户反馈。
398:                     log.warn("飞书图片读取失败：taskId={}, errorType={}", task.id(), exception.getClass().getSimpleName());
399:                     finish(task.id(), Execution.FAILED,
400:                             "图片读取失败：仅支持 10 MiB 以内的 PNG、JPEG、WebP 或 GIF，请调整后重新发送。");
401:                     return;
402:                 }
403:             }
404:             FeishuAgentRunner.Reply reply = runner.run(task.sessionId(), task.runId(), task.turnId(), task.input(), images,
405:                     Duration.ofSeconds(config.executionTimeoutSeconds()), execution.control);
406:             synchronized (this) {
407:                 Execution state = reply.result() == null
408:                         ? "user".equals(reply.stopReason()) ? Execution.CANCELLED
409:                         : "shutdown".equals(reply.stopReason()) ? Execution.INTERRUPTED : Execution.FAILED
410:                         : switch (reply.result().status()) {
411:                     case COMPLETED -> Execution.SUCCEEDED;
412:                     case FAILED -> Execution.FAILED;
413:                     case CANCELLED -> "timeout".equals(reply.stopReason()) ? Execution.TIMED_OUT : Execution.CANCELLED;
414:                 };
415:                 finish(task.id(), state, reply.text());
416:             }
417:         } catch (RuntimeException exception) {
418:             log.error("飞书任务收尾失败：taskId={}, errorType={}", task.id(), exception.getClass().getSimpleName());
419:             freeze();
420:         } finally {
421:             synchronized (this) {
422:                 running.remove(task.id());
423:                 if (!closed && !faulted && (resetBarrier == null || !resetBarrier.blocked())) { dispatch(); delivery.pump(); }
424:             }
425:         }
426:     }
