428:     private void finish(String taskId, Execution state, String text) {
429:         pendingImages.remove(taskId);
430:         List<String> chunks = FeishuTextChunks.split(text);
431:         List<Part> parts = new ArrayList<>();
432:         for (int i = 0; i < chunks.size(); i++) parts.add(Part.builder().id(stableId(taskId + ":part:" + i))
433:                 .text(chunks.get(i)).status(Delivery.PENDING).build());
434:         store.update(taskId, task -> task.toBuilder().state(state).input(null).finishedAt(clock.millis()).parts(parts).build());
435:         delivery.discardNotices(taskId);
436:         log.info("飞书任务已保存终态：taskId={}, state={}, outputLength={}, parts={}",
437:                 taskId, state, text == null ? 0 : text.length(), parts.size());
438:     }
