442:     private void recover() {
443:         for (Task task : store.snapshot().tasks()) {
444:             if (task.state().active()) {
445:                 TranscriptMessageDto saved = task.sessionId() == null ? null : transcripts.list(task.sessionId()).stream()
446:                         .filter(m -> task.turnId().equals(m.turnId()) && m.role() == TranscriptMessageDto.MessageRole.ASSISTANT)
447:                         .findFirst().orElse(null);
448:                 if (saved != null && saved.status() == TranscriptMessageDto.MessageStatus.COMPLETED) {
449:                     finish(task.id(), Execution.SUCCEEDED, saved.content());
450:                 } else finish(task.id(), Execution.INTERRUPTED, "服务已重启，本条任务已中断且不会自动重新执行。请检查实际结果后决定是否重新发起。");
451:             } else if (task.parts().stream().anyMatch(p -> p.status() == Delivery.SENDING)) {
452:                 store.update(task.id(), t -> t.toBuilder().parts(t.parts().stream().map(part -> part.status() == Delivery.SENDING
453:                         ? part.toBuilder().status(Delivery.UNKNOWN).errorCode("restart_during_send").build() : part).toList()).build());
454:                 delivery.notice(task, "recovery", "服务曾在发送回复时中断，发送状态不确定，完整结果已保留。补发可能重复；确认后请发送 /resend "
455:                         + task.id(), true, () -> true);
456:             }
457:         }
458:     }
