474:     public void close() {
475:         synchronized (this) {
476:             if (closed) return;
477:             closed = true;
478:             if (scheduler != null) scheduler.shutdownNow();
479:             running.values().forEach(execution -> execution.control.stop("shutdown"));
480:             workers.shutdown();
