483:             if (!workers.awaitTermination(15, TimeUnit.SECONDS)) workers.shutdownNow();
484:         } catch (InterruptedException exception) { workers.shutdownNow(); Thread.currentThread().interrupt(); }
485:         delivery.close();
486:         if (workers.isTerminated() && delivery.terminated()) {
487:             try { store.close(); } catch (IOException exception) { log.warn("飞书账本锁释放失败"); }
488:         } else log.error("仍有任务或发送未确认结束，保留渠道独占锁直到进程退出，禁止并行启动");
