23: /**
24:  * 管理用户级学习状态 SSE 订阅，并在事务提交后广播权威活动时段快照。
25:  *
26:  * <p>订阅注册、初始快照和变更广播通过同一监视器串行化，保证单条连接收到的
27:  * 首个事件一定是快照，且不会被更旧状态覆盖。</p>
28:  */
29: @Slf4j
30: @Service
31: @RequiredArgsConstructor
32: public class StudySessionStreamService {
33:     private final StudyService studyService;
34:     private final ConcurrentMap<String, Set<SseEmitter>> subscribers = new ConcurrentHashMap<>();
35:     private final Object lifecycleMonitor = new Object();
36:     private final String streamId = UUID.randomUUID().toString();
37:     private long revision;
38:     private boolean closing;
39: 
40:     /** 建立用户级订阅，并把当前活动时段作为首个快照发送。 */
41:     public SseEmitter subscribe(String ownerId) {
42:         SseEmitter emitter = new SseEmitter(0L);
43:         emitter.onCompletion(() -> unsubscribe(ownerId, emitter));
44:         emitter.onTimeout(() -> unsubscribe(ownerId, emitter));
45:         emitter.onError(ignored -> unsubscribe(ownerId, emitter));
46:         synchronized (lifecycleMonitor) {
47:             if (closing) {
48:                 emitter.complete();
49:                 return emitter;
50:             }
51:             subscribers.computeIfAbsent(ownerId, ignored -> ConcurrentHashMap.newKeySet()).add(emitter);
52:             try {
53:                 StudySession activeSession = studyService.getActive(ownerId);
54:                 send(ownerId, emitter, "snapshot",
55:                         new StudySessionStreamEvent(streamId, revision, "SNAPSHOT", null, activeSession));
56:             } catch (RuntimeException exception) {
57:                 unsubscribe(ownerId, emitter);
58:                 emitter.completeWithError(exception);
59:                 throw exception;
60:             }
61:         }
62:         return emitter;
63:     }
64: 
65:     /** 事务成功提交后，将最新权威状态广播给同一用户的所有连接。 */
66:     @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
67:     public void onStudySessionChanged(StudySessionChangedEvent event) {
68:         try {
69:             synchronized (lifecycleMonitor) {
70:                 if (closing) return;
71:                 Set<SseEmitter> ownerSubscribers = subscribers.get(event.ownerId());
72:                 if (ownerSubscribers == null || ownerSubscribers.isEmpty()) return;
73:                 StudySession activeSession = studyService.getActive(event.ownerId());
74:                 StudySessionStreamEvent payload = new StudySessionStreamEvent(
75:                         streamId, ++revision, event.changeType().name(), event.sessionId(), activeSession);
76:                 new ArrayList<>(ownerSubscribers)
77:                         .forEach(emitter -> send(event.ownerId(), emitter, "changed", payload));
78:             }
79:         } catch (RuntimeException exception) {
80:             // 数据已提交，实时通知失败不能把成功写入伪装成接口失败；重连快照会恢复权威状态。
81:             log.error("学习状态已提交但实时通知失败：ownerId={}, sessionId={}",
82:                     event.ownerId(), event.sessionId(), exception);
83:         }
84:     }
85: 
86:     /** 在应用退出前主动结束无限超时的 SSE，避免阻塞 WebServer 优雅停机。 */
87:     @EventListener(ContextClosedEvent.class)
88:     public void onApplicationContextClosed() {
89:         List<SseEmitter> emitters;
90:         synchronized (lifecycleMonitor) {
91:             closing = true;
92:             emitters = subscribers.values().stream().flatMap(Set::stream).toList();
93:             subscribers.clear();
94:         }
95:         emitters.forEach(SseEmitter::complete);
96:         if (!emitters.isEmpty()) {
97:             log.info("应用关闭前已结束 {} 个学习状态 SSE 订阅", emitters.size());
98:         }
99:     }
100: 
101:     private void send(String ownerId, SseEmitter emitter, String eventName, StudySessionStreamEvent payload) {
102:         try {
103:             emitter.send(SseEmitter.event().name(eventName).data(payload));
104:         } catch (IOException | IllegalStateException exception) {
105:             log.debug("学习状态 SSE 客户端已断开：ownerId={}", ownerId, exception);
106:             unsubscribe(ownerId, emitter);
107:             emitter.complete();
108:         }
109:     }
110: 
111:     private void unsubscribe(String ownerId, SseEmitter emitter) {
112:         Set<SseEmitter> ownerSubscribers = subscribers.get(ownerId);
113:         if (ownerSubscribers == null) return;
114:         ownerSubscribers.remove(emitter);
115:         if (ownerSubscribers.isEmpty()) subscribers.remove(ownerId, ownerSubscribers);
116:     }
117: 
118:     int subscriberCount() {
119:         return subscribers.values().stream().mapToInt(Set::size).sum();
120:     }
121: }

