16:     #[link(name = "ApplicationServices", kind = "framework")]
17:     extern "C" {
18:         fn CGEventSourceSecondsSinceLastEventType(state: i32, event: u32) -> f64;
19:         fn CGSessionCopyCurrentDictionary() -> *const c_void;
20:     }
21:     #[link(name = "CoreFoundation", kind = "framework")]
22:     extern "C" {
23:         fn CFStringCreateWithCString(allocator: *const c_void, text: *const i8, encoding: u32) -> *const c_void;
24:         fn CFDictionaryGetValue(dictionary: *const c_void, key: *const c_void) -> *const c_void;
25:         fn CFBooleanGetValue(value: *const c_void) -> bool;
26:         fn CFRelease(value: *const c_void);
27:     }
28:     unsafe {
29:         let idle = CGEventSourceSecondsSinceLastEventType(1, u32::MAX);
30:         let session = CGSessionCopyCurrentDictionary();
31:         if session.is_null() || !idle.is_finite() || idle < 0.0 {
32:             if !session.is_null() { CFRelease(session); }
33:             return Activity { idle_seconds: 0, locked: true, supported: false };
34:         }
35:         // 会话字典的锁屏键存在时暂停；控制台会话缺失时也安全暂停。
36:         let bool_value = |name: &str| -> Option<bool> {
37:             let name = CString::new(name).expect("fixed dictionary key");
38:             let key = CFStringCreateWithCString(std::ptr::null(), name.as_ptr(), 0x08000100);
39:             let value = CFDictionaryGetValue(session, key);
40:             let result = if value.is_null() { None } else { Some(CFBooleanGetValue(value)) };
41:             CFRelease(key); result
42:         };
43:         let locked = bool_value("CGSSessionScreenIsLocked").unwrap_or(false)
44:             || !bool_value("kCGSSessionOnConsoleKey").unwrap_or(false);
45:         CFRelease(session);
46:         Activity { idle_seconds: idle as u64, locked, supported: true }
47:     }
48: }
